//! Raw FFI for FFmpeg 7.1 (avcodec-61 / avformat-61 / avutil-59 / swresample-5 / swscale-8) and libmpv.
//! Bindings are generated by `src/bin/regen.rs` and committed; see that file to regenerate.

#[allow(warnings)]
#[path = "ffmpeg_sys.rs"]
pub mod ffmpeg;
#[allow(warnings)]
#[path = "mpv_sys.rs"]
pub mod mpv;

pub mod d3d11va;
pub mod media;

use std::ffi::{c_int, CStr};

/// `AVERROR(e)` from libavutil/error.h (POSIX errno → negative FFmpeg error).
pub const fn averror(errno: c_int) -> c_int {
    -errno
}
pub const EAGAIN: c_int = 11;
/// `AVERROR(EAGAIN)`: encoder/decoder wants more input / output not ready.
pub const AVERROR_EAGAIN: c_int = averror(EAGAIN);
/// `AVERROR_EOF` = `FFERRTAG('E','O','F',' ')` (libavutil/error.h; a macro bindgen cannot expand).
pub const AVERROR_EOF: c_int =
    -((b'E' as c_int) | ((b'O' as c_int) << 8) | ((b'F' as c_int) << 16) | ((b' ' as c_int) << 24));
/// `AV_NOPTS_VALUE` = `INT64_MIN` (libavutil/avutil.h).
pub const AV_NOPTS_VALUE: i64 = i64::MIN;

/// Human-readable text for an FFmpeg error code (`av_strerror`).
pub fn av_err_string(code: c_int) -> String {
    let mut buf = [0i8; 256];
    unsafe {
        ffmpeg::av_strerror(code, buf.as_mut_ptr(), buf.len());
        CStr::from_ptr(buf.as_ptr()).to_string_lossy().into_owned()
    }
}

/// FFmpeg build string, e.g. "n7.1.5-1-g7d0e842004-20260626".
pub fn ffmpeg_version() -> String {
    unsafe { CStr::from_ptr(ffmpeg::av_version_info()).to_string_lossy().into_owned() }
}

